'use client'
// Every design in src/designs/<slug>/ (meta.js + A.jsx, B.jsx…). The list itself is generated by
// scripts/registry.mjs, so adding a design or variant needs no registration anywhere.
import { generated } from './designs.generated'

export const designs = generated
  .map(({ slug, meta, keys, variants }) => ({ slug, ...meta, keys, components: variants }))
  .sort((a, b) => a.title.localeCompare(b.title))

export const getDesign = (slug) => designs.find((d) => d.slug === slug)
